INSERT INTO `soal` VALUES (1,2,'Ust. Mahfudz Ridwan','PG','C1','Numerasi — data dan ketidakpastian','Koperasi pondok mencatat penjualan selama satu pekan: Senin 42 unit, Selasa 55 unit,\nRabu 38 unit, Kamis 61 unit, Jumat 47 unit. Harga satu unit Rp 12.500. Pengurus ingin\nmengetahui hari dengan penjualan tertinggi dan rata-rata penjualan harian.','Berdasarkan data koperasi di atas, tentukan hari penjualan tertinggi.','A','Lihat kunci pada bahan ajar.',5.00,NULL,NULL,NULL,NULL,NULL,0,1,'2026-09-02 22:03:46.994','2026-09-02 22:03:46.994'),(2,2,'Ust. Mahfudz Ridwan','PG','C2','Numerasi — data dan ketidakpastian','Koperasi pondok mencatat penjualan selama satu pekan: Senin 42 unit, Selasa 55 unit,\nRabu 38 unit, Kamis 61 unit, Jumat 47 unit. Harga satu unit Rp 12.500. Pengurus ingin\nmengetahui hari dengan penjualan tertinggi dan rata-rata penjualan harian.','Berdasarkan data koperasi di atas, tentukan rata-rata penjualan harian.','B','Lihat kunci pada bahan ajar.',5.00,NULL,NULL,NULL,NULL,NULL,0,1,'2026-09-02 22:03:47.071','2026-09-02 22:03:47.071'),(3,2,'Ust. Mahfudz Ridwan','PG','C3','Numerasi — data dan ketidakpastian','Koperasi pondok mencatat penjualan selama satu pekan: Senin 42 unit, Selasa 55 unit,\nRabu 38 unit, Kamis 61 unit, Jumat 47 unit. Harga satu unit Rp 12.500. Pengurus ingin\nmengetahui hari dengan penjualan tertinggi dan rata-rata penjualan harian.','Berdasarkan data koperasi di atas, tentukan total pendapatan sepekan.','C','Lihat kunci pada bahan ajar.',5.00,NULL,NULL,NULL,NULL,NULL,0,1,'2026-09-02 22:03:47.146','2026-09-02 22:03:47.146'),(4,2,'Ust. Mahfudz Ridwan','PGK','C4','Bab 4',NULL,'Soal MAP-002 nomor 4: jelaskan konsep dasar fiqih pada tingkat C4.','A,C','Lihat kunci pada bahan ajar.',5.00,NULL,NULL,NULL,NULL,NULL,0,1,'2026-09-02 22:03:47.191','2026-09-02 22:03:47.191'),(5,2,'Ust. Mahfudz Ridwan','BS','C1','Bab 1',NULL,'Soal MAP-002 nomor 5: jelaskan konsep dasar fiqih pada tingkat C1.','A','Lihat kunci pada bahan ajar.',5.00,NULL,NULL,NULL,