INSERT INTO `unit` VALUES (5,'Poskestren','Poskestren','Layanan kesehatan santri.',1,'Poskestren Nurul Huda Mergosono','Layanan Kesehatan',NULL,NULL,2016,'/assets/logo-nuha.webp','Jl. Kol. Sugiono 3B No.103, Mergosono, Kedungkandang, Kota Malang, Jawa Timur','(0341) 361234','poskestrennuha@gmail.com',NULL,'Ns. Maimunah, S.Kep.','Penanggung Jawab Poskestren',NULL,'Santri sehat, pesantren bersih, layanan kesehatan yang tersistem.','Menyediakan layanan kesehatan dasar santri bersama Puskesmas Kedungkandang; mencatat riwayat kesehatan santri; menggerakkan perilaku hidup bersih dan sehat.',NULL,NULL,NULL),(6,'MA','MA','Kelas 10–12, IPA / IPS / Keagamaan.',1,'MA Nurul Huda Mergosono','MA','131235730021','B',2010,'/assets/logo-nuha.webp','Jl. Kol. Sugiono 3B No.103, Mergosono, Kedungkandang, Kota Malang, Jawa Timur','(0341) 361234','manuhamergosono@gmail.com','https://nuha.pesantren.web.id','Khalimatus Sa\'diyah, S.Si','Kepala Madrasah',NULL,'Madrasah yang unggul dalam tafaqquh fid-din dan siap melanjutkan ke perguruan tinggi.','Menguatkan penguasaan kitab dan Al-Qur’an; menyiapkan peminatan IPA, IPS, dan Keagamaan; membina karakter santri yang moderat.',NULL,NULL,NULL),(7,'SMP','SMP','Kelas 7–9, Kurikulum Merdeka.',1,'SMP Nurul Huda Mergosono','SMP','20539746','B',2004,'/assets/logo-nuha.webp','Jl. Kol. Sugiono 3B No.103, Mergosono, Kedungkandang, Kota Malang, Jawa Timur','(0341) 361234','smpnuhamergosono@gmail.com','https://nuha.pesantren.web.id','Drs. Sulaiman Hadi, M.Pd.','Kepala Sekolah',NULL,'Terwujudnya lulusan yang berakhlak pesantren, cakap akademik, dan mandiri.','Menyelenggarakan pembelajaran Kurikulum Merdeka yang berpadu dengan pembinaan diniyah; membiasakan ibadah dan adab harian; mengembangkan minat bakat santri.',NULL,NULL,NULL),(8,'Pondok','Madin','Program Tahfidz dan Kitab Kuning.',1,'Pondok Pesantren Salafiyah Syafi’iyah Nurul Huda Mergosono','Pesantren','512357301234',NULL,1970,'/assets/logo-nuha.webp','Jl. Kol. Sugiono 3B No.103, Mergosono, Kedungkandang, Kota Malang, Jawa Timur','(0341) 361234','ppssnuhamergosono@gmail.com','https://nuha.pesantren.web.id','Ust. Abdul Karim','Lurah Pondok',NULL,'Pesantren salaf yang kuat pada sanad kitab dan Al-Qur’an, terbuka pada tata kelola modern.','Menyelenggarakan pengajian kitab kuning berjenjang; membina hafalan Al-Qur’an; menanamkan adab dan kemandirian santri mukim.',NULL,NULL,NULL);
